Method.Implementation:
  #DIM status AS %Status
  set status = $$$OK
  try{
   ///set uuepdf = pRequest.StringValue
   Set tSC = ..GetConnection(.tJavaGateway)
   If $$$ISOK(tSC){
     $$$TRACE("Do Discrete data retrieve: "_pRequest.Url_" | "_pRequest.UsrId)
     set sddReader = ##class(com.ihc.itf.Syngo.SyngoDiscreteDataReader).%New(tJavaGateway)
	 If '$IsObject(sddReader){
	   $$$TRACE(">>>>>sddReader is not an object")
       Set sc = $System.Status.Error($$$GeneralError,"DiscreteDataReader is null.")
       Quit
     }
     $$$TRACE("Connect to Syngo DB ...")
     do sddReader.connectSyngoDB(pRequest.Url, pRequest.UsrId, pRequest.Psswrd)
	 set pResponse=##class(Ens.StringResponse).%New()
	 set pResponse.StringValue=""
	 $$$TRACE("Retrieve EF ...")
	 set sdd = sddReader.getEjectionFractionData(pRequest.AccessNo, pRequest.Dept)
	 $$$TRACE("Returned:"_sdd)
     set pResponse.StringValue=sdd
     do sddReader.close()
   }	
  }catch err{   
    If '$IsObject(sddReader){
	  do sddReader.close()
    }
    Kill tJavaGateway
	$$$TRACE("Exception Calling EF reader: " _ err)
	set status = $$$ERROR("Exception in DiscreteDataReader Operation")
  }

  return status
